{
    public const string Content = """
<!doctype html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#101827"><title>لوحة وشوشني</title>
<style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172033;background:#f3f5f9;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer;border:0;border-radius:10px;padding:10px 14px;background:#3456d1;color:#fff;font-weight:700}button.secondary{background:#e8ecf5;color:#24304a}button.danger{background:#c0394b}button.success{background:#16835d}.hidden{display:none!important}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:22px;background:radial-gradient(circle at 15% 10%,#dce5ff,#f3f5f9 45%)}.login-card{width:min(440px,100%);background:white;border-radius:22px;padding:32px;box-shadow:0 20px 70px #192b5120}.login-card h1{margin:0 0 8px}.login-card p{color:#62708a}.login-card label{display:block;margin:18px 0 7px;font-weight:700}.login-card input{width:100%;padding:12px;border:1px solid #d8deea;border-radius:10px}.login-card button{width:100%;margin-top:20px}.shell{min-height:100vh;display:grid;grid-template-columns:245px 1fr}.side{background:#101827;color:white;padding:25px 16px;display:flex;flex-direction:column;gap:7px}.brand{font-size:22px;font-weight:800;padding:6px 10px 24px}.brand small{display:block;color:#9ba8bd;font-size:12px;margin-top:7px}.nav{background:transparent;color:#cbd4e3;text-align:right}.nav.active,.nav:hover{background:#26344b;color:#fff}.side .logout{margin-top:auto;background:#26344b}.main{padding:28px;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.top h1{margin:0;font-size:26px}.muted{color:#738098}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:22px}.card,.panel{background:#fff;border:1px solid #e5e9f1;border-radius:16px;padding:18px;box-shadow:0 4px 14px #24365b08}.metric{color:#748098;font-size:13px}.metric strong{display:block;color:#1d2940;font-size:27px;margin-top:10px}.grid2{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}.panel h2{font-size:18px;margin:0 0 16px}.tools{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:14px}.tools input,.tools select{border:1px solid #d8deea;background:white;border-radius:9px;padding:10px;min-width:150px}.table-wrap{overflow:auto;border:1px solid #e7ebf2;border-radius:12px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:right;padding:12px;border-bottom:1px solid #edf0f5;white-space:nowrap}th{font-size:12px;color:#738098;background:#f8f9fc}td{font-size:13px}.badge{display:inline-block;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:700;background:#e9edf5;color:#41506a}.badge.Approved{background:#def5e9;color:#12633e}.badge.Pending{background:#fff1ce;color:#885c00}.badge.Rejected{background:#ffe2e3;color:#922c36}.badge.blocked{background:#ffe2e3;color:#922c36}.badge.active{background:#def5e9;color:#12633e}.actions{display:flex;gap:6px}.actions button{padding:7px 9px;font-size:12px}.pager{display:flex;align-items:center;gap:10px;justify-content:center;margin-top:14px}.empty,.error{padding:24px;text-align:center;color:#738098}.error{color:#ad2838}.trend{display:flex;align-items:end;gap:7px;min-height:160px;border-bottom:1px solid #e4e8f0;padding:8px 4px}.barbox{flex:1;text-align:center;min-width:10px;font-size:10px;color:#78859b}.bar{margin:auto auto 5px;width:min(25px,80%);min-height:3px;background:linear-gradient(#6f86ec,#3456d1);border-radius:5px 5px 0 0}.status-list{display:grid;gap:11px}.status-row{display:flex;justify-content:space-between;border-bottom:1px solid #eff1f5;padding:7px 0}.toolbar-actions{display:flex;gap:8px;align-items:center}dialog{border:0;border-radius:16px;max-width:540px;width:calc(100% - 30px);padding:24px;box-shadow:0 20px 70px #0003}dialog::backdrop{background:#10182788}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px}.detail{background:#f5f7fb;border-radius:10px;padding:11px}.detail b{display:block;color:#738098;font-size:12px;margin-bottom:6px}.toast{position:fixed;bottom:20px;left:20px;background:#172033;color:white;padding:12px 16px;border-radius:10px;z-index:3}.system{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.system .card{box-shadow:none}.system strong{display:block;margin-top:8px}.login-error{color:#b32639;min-height:20px;margin-top:12px}
@media(max-width:1000px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.grid2{grid-template-columns:1fr}}@media(max-width:700px){.shell{grid-template-columns:1fr}.side{padding:13px;position:sticky;top:0;z-index:2;display:flex;flex-direction:row;overflow:auto;align-items:center}.brand{font-size:16px;padding:5px 8px;white-space:nowrap}.brand small{display:none}.nav{white-space:nowrap;padding:9px 11px}.side .logout{margin:0 0 0 auto;white-space:nowrap}.main{padding:17px}.top h1{font-size:21px}.cards{gap:9px}.card{padding:13px}.metric strong{font-size:23px}.details{grid-template-columns:1fr}.tools>*{flex:1}}
</style>
</head>
<body>
<section id="login" class="login-wrap"><form id="loginForm" class="login-card"><div style="font-size:38px">🎓</div><h1>لوحة وشوشني</h1><p>إدارة آمنة لمستخدمي البوت وطلبات الانضمام</p><label for="username">اسم المستخدم</label><input id="username" autocomplete="username" required><label for="password">كلمة المرور</label><input id="password" type="password" autocomplete="current-password" required><div class="login-error" id="loginError"></div><button type="submit">دخول</button></form></section>
<div id="app" class="shell hidden"><aside class="side"><div class="brand">وشوشني<small>لوحة الإدارة</small></div><button class="nav active" data-page="overview">نظرة عامة</button><button class="nav" data-page="users">كل المستخدمين</button><button class="nav" data-page="Pending">طلبات معلقة</button><button class="nav" data-page="Approved">المعتمدون</button><button class="nav" data-page="Rejected">المرفوضون</button><button class="nav" data-page="blocked">المحظورون</button><button class="nav" data-page="audit">سجل التدقيق</button><button class="nav" data-page="system">حالة النظام</button><button id="logout" class="logout">تسجيل الخروج</button></aside><main class="main"><div class="top"><div><h1 id="pageTitle">نظرة عامة</h1><div class="muted" id="subtitle">بيانات مباشرة من قاعدة البيانات</div></div><button class="secondary" id="refresh">تحديث</button></div><div id="content"></div></main></div><dialog id="userDialog"><h2>تفاصيل المستخدم</h2><div id="userDetails" class="details"></div><div style="text-align:left;margin-top:18px"><button class="secondary" onclick="document.getElementById('userDialog').close()">إغلاق</button></div></dialog><div id="toast" class="toast hidden"></div>
<script>
let csrf='',pageName='overview',usersPage=1,auditPage=1,filters={},auditFilters={};const $=id=>document.getElementById(id),esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function refreshCsrf(){const r=await fetch('/admin/api/csrf',{credentials:'same-origin'});let d=null;try{d=await r.json()}catch{}if(!r.ok||!d?.requestToken)throw Error('تعذر تهيئة جلسة تسجيل الدخول (HTTP '+r.status+'). أعد تحميل الصفحة، وإذا استمر الخطأ فتحقق من نشر خدمة البوت.');csrf=d.requestToken}
async function api(path,options={}){const headers={...(options.headers||{})};if(options.method&&options.method!=='GET'){headers['X-CSRF-TOKEN']=csrf;headers['Content-Type']='application/json'}const r=await fetch('/admin/api'+path,{...options,headers,credentials:'same-origin'});if(r.status===401&&path!='/login'){showLogin();throw Error('انتهت الجلسة، سجّل الدخول مجدداً.')}const body=r.status===204?null:await r.json().catch(()=>null);if(!r.ok)throw Error(body?.error||body?.detail||(r.status===401?'بيانات الدخول غير صحيحة.':'تعذر تنفيذ الطلب.'));return body}
function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),3200)}function showLogin(){$('app').classList.add('hidden');$('login').classList.remove('hidden')}
function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden');loadPage('overview')}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').textContent='';try{await refreshCsrf();await api('/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});await refreshCsrf();$('password').value='';showApp()}catch(err){$('loginError').textContent=err.message}});
$('logout').onclick=async()=>{try{await api('/logout',{method:'POST',body:'{}'})}catch{}await refreshCsrf().catch(()=>{});showLogin()};$('refresh').onclick=()=>loadPage(pageName);document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');usersPage=1;loadPage(b.dataset.page)});
async function loadPage(p){pageName=p;const names={overview:'نظرة عامة',users:'كل المستخدمين',Pending:'طلبات معلقة',Approved:'المستخدمون المعتمدون',Rejected:'المستخدمون المرفوضون',blocked:'المستخدمون المحظورون',audit:'سجل التدقيق',system:'حالة النظام'};$('pageTitle').textContent=names[p]||p;$('content').innerHTML='<div class="panel empty">جاري تحميل البيانات…</div>';try{if(p==='overview')await overview();else if(p==='audit')await audit();else if(p==='system')await system();else await usersList(p)}catch(e){$('content').innerHTML='<div class="panel error">'+esc(e.message)+'</div>'}}
async function overview(){const d=await api('/overview');const s=d.statistics;$('content').innerHTML='<div class="cards">'+[['إجمالي المستخدمين',s.totalUsers],['معتمدون',s.approvedUsers],['بانتظار الموافقة',s.pendingUsers],['مرفوضون',s.rejectedUsers],['محظورون',s.blockedUsers],['نشطون',s.activeUsers],['حسابات Moodle المرتبطة',s.moodleLinkedUsers]].map(x=>'<div class="card"><div class="metric">'+x[0]+'</div><strong>'+x[1]+'</strong></div>').join('')+'</div><div class="grid2"><section class="panel"><h2>تسجيلات آخر 30 يوماً</h2><div class="trend">'+(d.registrations.length?d.registrations.map(x=>'<div class="barbox"><div class="bar" style="height:'+Math.max(4,Math.min(130,x.count*12))+'px"></div>'+esc(x.date.slice(5))+'<br>'+x.count+'</div>').join(''):'<div class="empty">لا توجد تسجيلات في هذه الفترة</div>')+'</div></section><section class="panel"><h2>الحسابات حسب الحالة</h2><div class="status-list"><div class="status-row"><span>معتمدون</span><b>'+s.approvedUsers+'</b></div><div class="status-row"><span>قيد المراجعة</span><b>'+s.pendingUsers+'</b></div><div class="status-row"><span>مرفوضون</span><b>'+s.rejectedUsers+'</b></div><div class="status-row"><span>محظورون (مستقل عن الحالة)</span><b>'+s.blockedUsers+'</b></div></div></section></div>'}
function userTable(items){if(!items.length)return '<div class="empty">لا يوجد مستخدمون مطابقون.</div>';return '<div class="table-wrap"><table><thead><tr><th>الاسم</th><th>Telegram</th><th>الحالة</th><th>الوصول</th><th>Moodle</th><th>التسجيل</th><th>آخر نشاط</th><th>إجراءات</th></tr></thead><tbody>'+items.map(x=>{const u=x.registration;const name=[u.firstName,u.lastName].filter(Boolean).join(' ')||'—';return '<tr><td><a href="#" onclick="details('+u.telegramUserId+');return false">'+esc(name)+'</a></td><td>'+esc(u.username?'@'+u.username:u.telegramUserId)+'<br><small>'+esc(u.telegramUserId)+'</small></td><td><span class="badge '+esc(u.status)+'">'+({Pending:'معلق',Approved:'معتمد',Rejected:'مرفوض'}[u.status]||esc(u.status))+'</span></td><td><span class="badge '+(u.isBlocked?'blocked':'active')+'">'+(u.isBlocked?'محظور':'نشط')+'</span></td><td>'+ (x.moodleLinked?'مرتبط':'غير مربوط')+'</td><td>'+date(u.registeredAt)+'<br><small>قرار: '+date(u.decisionAt)+'</small></td><td>'+date(u.lastActivityAt)+'</td><td><div class="actions">'+actionButtons(u)+'</div></td></tr>'}).join('')+'</tbody></table></div>'}
function actionButtons(u){let a=[];if(u.status==='Pending')a.push('<button class="success" onclick="statusAction('+u.telegramUserId+',\'Approved\')">اعتماد</button><button class="secondary" onclick="statusAction('+u.telegramUserId+',\'Rejected\')">رفض الطلب</button>');else if(u.status==='Rejected')a.push('<button class="success" onclick="statusAction('+u.telegramUserId+',\'Approved\')">إعادة اعتماد</button>');else if(u.status==='Approved')a.push('<button class="secondary" onclick="revokeAction('+u.telegramUserId+')">سحب الاعتماد</button>');if(u.isBlocked)a.push('<button class="success" onclick="unblock('+u.telegramUserId+')">رفع الحظر</button>');else a.push('<button class="danger" onclick="block('+u.telegramUserId+')">حظر</button>');return a.join('')}
function date(v){if(!v)return '—';try{return new Intl.DateTimeFormat('ar',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return esc(v)}}
async function usersList(p){const status=['Pending','Approved','Rejected'].includes(p)?p:null;const blocked=p==='blocked';let q=new URLSearchParams({page:String(usersPage),pageSize:'20',sort:filters.sort||'newest'});if(status)q.set('status',status);if(blocked)q.set('blocked','true');if(filters.search)q.set('search',filters.search);if(filters.blocked&&p==='users')q.set('blocked',filters.blocked);if(filters.status&&p==='users')q.set('status',filters.status);const d=await api('/users?'+q);$('content').innerHTML='<div class="tools"><input id="search" placeholder="ابحث بالاسم أو username أو Telegram ID" value="'+esc(filters.search||'')+'"><select id="statusFilter"><option value="">كل الحالات</option><option value="Pending">قيد المراجعة</option><option value="Approved">معتمد</option><option value="Rejected">مرفوض</option></select><select id="blockFilter"><option value="">كل حالات الوصول</option><option value="false">نشط</option><option value="true">محظور</option></select><select id="sortFilter"><option value="newest">الأحدث تسجيلاً</option><option value="oldest">الأقدم تسجيلاً</option></select><button id="applyFilter">بحث وتصفية</button></div><section class="panel">'+userTable(d.users)+'</section><div class="pager"><button class="secondary" '+(d.page<=1?'disabled':'')+' id="prev">السابق</button><span>صفحة '+d.page+' — '+d.total+' مستخدم</span><button class="secondary" '+(d.page*d.pageSize>=d.total?'disabled':'')+' id="next">التالي</button></div>';$('statusFilter').value=filters.status||'';$('blockFilter').value=filters.blocked||'';$('sortFilter').value=filters.sort||'newest';$('applyFilter').onclick=()=>{filters={...filters,search:$('search').value,status:$('statusFilter').value,blocked:$('blockFilter').value,sort:$('sortFilter').value};usersPage=1;loadPage(p)};$('search').onkeydown=e=>{if(e.key==='Enter')$('applyFilter').click()};$('prev').onclick=()=>{usersPage--;loadPage(p)};$('next').onclick=()=>{usersPage++;loadPage(p)}}
async function statusAction(id,status){const promptText=status==='Approved'?'تأكيد اعتماد المستخدم؟':'تأكيد رفض الطلب المعلّق؟';if(!confirm(promptText))return;try{await api('/users/'+id+'/status',{method:'POST',body:JSON.stringify({status,reason:null})});toast('تم تحديث حالة المستخدم.');loadPage(pageName)}catch(e){toast(e.message)}}async function revokeAction(id){if(!confirm('تأكيد سحب اعتماد هذا المستخدم؟ سيتوقف عن استخدام البوت.'))return;try{await api('/users/'+id+'/revoke',{method:'POST',body:JSON.stringify({status:'Rejected',reason:null})});toast('تم سحب الاعتماد.');loadPage(pageName)}catch(e){toast(e.message)}}async function block(id){if(!confirm('تأكيد حظر هذا المستخدم؟'))return;const reason=prompt('سبب الحظر (اختياري):');try{await api('/users/'+id+'/block',{method:'POST',body:JSON.stringify({reason})});toast('تم حظر المستخدم.');loadPage(pageName)}catch(e){toast(e.message)}}async function unblock(id){if(!confirm('تأكيد رفع الحظر؟ ستبقى حالة التسجيل كما هي.'))return;try{await api('/users/'+id+'/unblock',{method:'POST',body:'{}'});toast('تم رفع الحظر.');loadPage(pageName)}catch(e){toast(e.message)}}
async function details(id){try{const x=await api('/users/'+id),u=x.registration;const data=[['الاسم',[u.firstName,u.lastName].filter(Boolean).join(' ')],['Telegram username',u.username?'@'+u.username:null],['Telegram ID',u.telegramUserId],['تاريخ التسجيل',date(u.registeredAt)],['الحالة',u.status],['الوصول',u.isBlocked?'محظور':'نشط'],['قرار المسؤول',date(u.decisionAt)],['Moodle',x.moodleLinked?'مرتبط':'غير مربوط'],['آخر نشاط',date(u.lastActivityAt)],['تاريخ الحظر',date(u.blockedAt)],['سبب الحظر',u.blockReason],['المسؤول',u.blockedBy]].map(([a,b])=>'<div class="detail"><b>'+esc(a)+'</b>'+esc(b)+'</div>').join('');$('userDetails').innerHTML=data+'<div class="actions" style="grid-column:1/-1">'+actionButtons({...u,telegramUserId:id})+'</div>';$('userDialog').showModal()}catch(e){toast(e.message)}}
async function audit(){const q=new URLSearchParams({page:String(auditPage),pageSize:'50'});for(const [k,v] of Object.entries(auditFilters))if(v)q.set(k,v);const d=await api('/audit?'+q);$('content').innerHTML='<div class="tools"><select id="auditAction"><option value="">كل الإجراءات</option>'+['Registered','Approved','Rejected','Revoked','Blocked','Unblocked'].map(x=>'<option>'+x+'</option>').join('')+'</select><input id="auditTarget" type="number" placeholder="Telegram ID"><input id="auditFrom" type="date" aria-label="من تاريخ"><input id="auditTo" type="date" aria-label="إلى تاريخ"><button id="auditSearch">تصفية</button></div><section class="panel">'+(d.length?'<div class="table-wrap"><table><thead><tr><th>الوقت</th><th>الإجراء</th><th>المستخدم المستهدف</th><th>المسؤول</th><th>السبب</th><th>من</th><th>إلى</th></tr></thead><tbody>'+d.map(x=>'<tr><td>'+date(x.occurredAt)+'</td><td>'+esc(x.actionType)+'</td><td>'+esc(x.targetTelegramUserId)+'</td><td>'+esc(x.administrator)+'</td><td>'+esc(x.reason)+'</td><td>'+esc(x.previousState)+'</td><td>'+esc(x.newState)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">لا توجد أحداث تدقيق.</div>')+'</section><div class="pager"><button class="secondary" id="auditPrev">السابق</button><span>صفحة '+auditPage+'</span><button class="secondary" id="auditNext">التالي</button></div>';$('auditAction').value=auditFilters.action||'';$('auditTarget').value=auditFilters.target||'';$('auditFrom').value=(auditFilters.from||'').slice(0,10);$('auditTo').value=auditFilters.to?new Date(new Date(auditFilters.to).getTime()-86400000).toISOString().slice(0,10):'';$('auditSearch').onclick=()=>{auditFilters={action:$('auditAction').value,target:$('auditTarget').value,from:$('auditFrom').value?new Date($('auditFrom').value).toISOString():null,to:$('auditTo').value?new Date(new Date($('auditTo').value).getTime()+86400000).toISOString():null};auditPage=1;loadPage('audit')};$('auditPrev').onclick=()=>{if(auditPage>1){auditPage--;loadPage('audit')}};$('auditNext').onclick=()=>{auditPage++;loadPage('audit')}}
async function system(){const d=await api('/overview');const s=d.system,items=[['التطبيق',s.application],['قاعدة البيانات',s.database],['استطلاع Telegram',s.telegramPolling],['آخر تحديث Telegram',date(s.lastTelegramUpdate)],['Gemini',s.gemini],['Moodle',s.moodle]];$('content').innerHTML='<div class="system">'+items.map(x=>'<div class="card"><div class="metric">'+x[0]+'</div><strong>'+esc(x[1])+'</strong></div>').join('')+'</div><p class="muted">حالة Moodle هنا تعكس اكتمال إعداد التكامل فقط، ولا تعني أن جلسة أي مستخدم صالحة.</p>'}
refreshCsrf().then(()=>api('/me').then(showApp).catch(showLogin));
</script></body></html>
""";
}
